conteudo:
create type record_status as enum ('ativo', 'inativo');
create type weight_level as enum ('baixo', 'medio', 'alto');
create type learning_level as enum ('novo', 'aprendendo', 'consolidando', 'dominado');
create type risk_level as enum ('baixo', 'medio', 'alto', 'muito_alto');
create type study_type as enum ('questao', 'simulado', 'discursiva', 'revisao', 'flashcard', 'leitura', 'videoaula');
create type contact_type as enum ('primeira_tentativa', 'revisao');
create type confidence_level as enum ('baixa', 'media', 'alta');;

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  display_name text,
  timezone text not null default 'America/Fortaleza',
  preferences jsonb not null default '{}'::jsonb,
  is_admin boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public.profiles is 'Perfil do usuário. is_admin controla escrita nas tabelas de catálogo (ver TEC-008/TEC-009).';;

create table public.exam_boards (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references auth.users(id) on delete cascade,
  name text not null,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

comment on column public.exam_boards.metadata is 'Inclui scoring_type quando a regra de pontuação por banca for definida (NEG-010) — não criar coluna dedicada antes disso.';

create unique index exam_boards_global_name_uk on public.exam_boards (lower(name)) where user_id is null;
create unique index exam_boards_personal_name_uk on public.exam_boards (user_id, lower(name)) where user_id is not null;
create index exam_boards_user_id_idx on public.exam_boards (user_id);;

create table public.disciplines (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references auth.users(id) on delete cascade,
  name text not null,
  category text,
  status record_status not null default 'ativo',
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create unique index disciplines_global_name_uk on public.disciplines (lower(name)) where user_id is null;
create unique index disciplines_personal_name_uk on public.disciplines (user_id, lower(name)) where user_id is not null;
create index disciplines_user_id_idx on public.disciplines (user_id);
create index disciplines_status_idx on public.disciplines (status);;

create table public.exams (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references auth.users(id) on delete cascade,
  board_id uuid references public.exam_boards(id) on delete set null,
  name text not null,
  year int,
  role text,
  area text,
  exam_date date,
  status record_status not null default 'ativo',
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index exams_user_id_idx on public.exams (user_id);
create index exams_board_id_idx on public.exams (board_id);
create index exams_status_idx on public.exams (status);;

create table public.exam_disciplines (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  exam_id uuid not null references public.exams(id) on delete cascade,
  discipline_id uuid not null references public.disciplines(id) on delete cascade,
  weight weight_level not null,
  target_accuracy numeric(5,2) check (target_accuracy is null or (target_accuracy >= 0 and target_accuracy <= 100)),
  expected_questions int check (expected_questions is null or expected_questions >= 0),
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique (user_id, exam_id, discipline_id)
);

create index exam_disciplines_user_id_idx on public.exam_disciplines (user_id);
create index exam_disciplines_exam_id_idx on public.exam_disciplines (exam_id);
create index exam_disciplines_discipline_id_idx on public.exam_disciplines (discipline_id);;

create table public.question_sets (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references auth.users(id) on delete cascade,
