create or replace function public.set_updated_at()
returns trigger as $$
begin
  new.updated_at = now();
  return new;
end;
$$ language plpgsql;

create trigger profiles_set_updated_at
before update on public.profiles
for each row execute function public.set_updated_at();

create trigger user_parameters_set_updated_at
before update on public.user_parameters
for each row execute function public.set_updated_at();;

create policy profiles_select_own on public.profiles
for select to authenticated
using (id = auth.uid());

create policy profiles_insert_own on public.profiles
for insert to authenticated
with check (id = auth.uid());

create policy profiles_update_own on public.profiles
for update to authenticated
using (id = auth.uid())
with check (id = auth.uid());

create or replace function public.protect_is_admin()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if (new.is_admin is distinct from old.is_admin) and not public.is_admin() then
    new.is_admin := old.is_admin;
  end if;
  return new;
end;
$$;

create trigger profiles_protect_is_admin
before update on public.profiles
for each row execute function public.protect_is_admin();;

do $$
declare
  t text;
begin
  foreach t in array array['exam_boards','disciplines','exams','question_sets','questions','risk_rules']
  loop
    execute format($f$
      create policy %1$s_select on public.%1$s
      for select to authenticated
      using (user_id is null or user_id = auth.uid());
    $f$, t);

    execute format($f$
      create policy %1$s_insert on public.%1$s
      for insert to authenticated
      with check (user_id = auth.uid() or (user_id is null and public.is_admin()));
    $f$, t);

    execute format($f$
      create policy %1$s_update on public.%1$s
      for update to authenticated
      using (user_id = auth.uid() or (user_id is null and public.is_admin()))
      with check (user_id = auth.uid() or (user_id is null and public.is_admin()));
    $f$, t);

    execute format($f$
      create policy %1$s_delete on public.%1$s
      for delete to authenticated
      using (user_id = auth.uid() or (user_id is null and public.is_admin()));
    $f$, t);
  end loop;
end;
$$;;

do $$
declare
  t text;
begin
  foreach t in array array['exam_disciplines','study_sessions','session_results','question_attempts','user_parameters']
  loop
    execute format($f$
      create policy %1$s_all_own on public.%1$s
      for all to authenticated
      using (user_id = auth.uid())
      with check (user_id = auth.uid());
    $f$, t);
  end loop;
end;
$$;;

create or replace function public.set_updated_at()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

revoke execute on function public.handle_new_user() from anon, authenticated;
revoke execute on function public.protect_is_admin() from anon, authenticated;
revoke execute on function public.is_admin() from anon;;

