-- Correção: somar quantidade em TODOS os níveis da hierarquia contava a mesma
-- questão várias vezes (nó pai já inclui a contagem dos filhos no índice do
-- TEC). is_leaf marca os nós-folha (sem subitem próprio) -- somar só esses
-- bate exatamente com o total de cada banca (validado: Cebraspe 3425, FCC
-- 1315, Vunesp 2501, FGV 2027 -- conferido direto nos arquivos originais).
alter table public.historical_question_stats add column is_leaf boolean not null default false;
create index historical_question_stats_is_leaf_idx on public.historical_question_stats (is_leaf) where is_leaf;
;

-- Fase 4 (extensão) — Multibancas por sessão (decisão de 02/07/2026): uma
-- sessão de estudo pode referenciar mais de uma banca simultaneamente (ex.:
-- simulado misturando questões de bancas diferentes). study_sessions.board_id
-- é mantido como está (campo legado/atalho, usado quando só uma banca é
-- informada); study_session_boards é a fonte de verdade para múltiplas
-- bancas e para qualquer consumo futuro (ex. recorrência histórica por banca
-- combinada, Fase 5-B).

create table public.study_session_boards (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  session_id uuid not null references public.study_sessions(id) on delete cascade,
  board_id uuid not null references public.exam_boards(id) on delete restrict,
  created_at timestamptz not null default now(),
  unique (session_id, board_id)
);

comment on table public.study_session_boards is
  'Bancas associadas a uma sessão de estudo (0..N). Suporta múltiplas bancas por sessão (ex. simulado misto). study_sessions.board_id continua existindo como atalho para o caso de banca única — não foi removido.';

create index study_session_boards_session_id_idx on public.study_session_boards (session_id);
create index study_session_boards_board_id_idx on public.study_session_boards (board_id);
create index study_session_boards_user_id_idx on public.study_session_boards (user_id);

-- Backfill: toda sessão que já tem board_id preenchido ganha 1 linha aqui,
-- para as duas fontes ficarem consistentes desde já.
insert into public.study_session_boards (user_id, session_id, board_id)
select user_id, id, board_id
from public.study_sessions
where board_id is not null
on conflict (session_id, board_id) do nothing;

create policy study_session_boards_all_own on public.study_session_boards
for all to authenticated
using (user_id = auth.uid())
with check (user_id = auth.uid());
;

-- Aditivo, sem conflito com decisão anterior: adiciona valores que nunca
-- existiram nesses enums (ALTER TYPE ADD VALUE não quebra nada existente).
-- 'critico' em learning_level: nível de aprendizado com desempenho ruim mas
-- já com dado (distinto de 'novo' = ainda sem prática/dado). Vem da matriz
-- de risco real do usuário (planilha Excel, coluna "Nível Atual").
alter type learning_level add value if not exists 'critico';
-- 'muito_baixo' em risk_level: a matriz do usuário tem 5 níveis de risco
-- (a tabela atual só ia até muito_alto, faltava o extremo oposto).
alter type risk_level add value if not exists 'muito_baixo';
;

-- Fase 10 (05/07/2026) — duas mudanças pedidas pelo usuário:
--
-- 1) Cadastro sob demanda (Nova Sessão) deixa de criar Concurso/Banca/
--    Disciplina/Caderno como "global" quando quem cadastra é admin. A partir
--    de agora TODO mundo (inclusive admin) cria como item pessoal
--    (user_id = quem criou) — novos usuários passam a ver essas 4 listas
--    vazias até cadastrarem os próprios itens, em vez de herdar o catálogo
--    de teste do admin. Promover algo pessoal pra global vira uma ação
--    manual (avisada caso a caso pelo usuário), não mais automática.
--
-- 2) Painel admin: precisa ver e editar/apagar o catálogo de TODOS os
--    usuários (não só o próprio). RLS de select/update/delete das 4 tabelas
--    ganha bypass de is_admin() sem a restrição "só se for global" que
--    existia antes (a policy antiga só deixava admin mexer em item global
--    OU próprio — não em item pessoal de outro usuário).

alter policy disciplines_select on disciplines
  using ((user_id is null) or (user_id = (select auth.uid())) or (select is_admin()));
alter policy disciplines_update on disciplines
  using ((user_id = (select auth.uid())) or (select is_admin()))
  with check ((user_id = (select auth.uid())) or (select is_admin()));
